<?php
require_once __DIR__.'/../alfa_acquiring.php';av_require_staff_api();if(!av_is_superadmin())av_json_response(array('ok'=>false,'error'=>'Только главный администратор'),403);
if($_SERVER['REQUEST_METHOD']!=='POST')av_json_response(array('ok'=>false,'error'=>'Метод не поддерживается'),405);$input=json_decode(file_get_contents('php://input'),true);if(!is_array($input))$input=array();if(!av_check_csrf($input['csrf']??''))av_json_response(array('ok'=>false,'error'=>'Сессия устарела'),403);
$orderId=trim((string)($input['order_id']??''));$orders=av_read_orders();$index=null;foreach($orders as $k=>$order)if(($order['id']??'')===$orderId){$index=$k;break;}if($index===null)av_json_response(array('ok'=>false,'error'=>'Заказ не найден'),404);
$order=$orders[$index];if(($order['payment_status']??'')!=='paid'||empty($order['alfa_order_id']))av_json_response(array('ok'=>false,'error'=>'Нет подтверждённого платежа для возврата'),422);$paid=(float)($order['paid_amount']??$order['alfa_amount']??0);$amount=(float)($input['amount']??$paid);if($amount<=0||$amount>$paid)av_json_response(array('ok'=>false,'error'=>'Некорректная сумма возврата'),422);
$response=av_alfa_request('refund.do',array('orderId'=>$order['alfa_order_id'],'amount'=>(int)round($amount*100),'language'=>'ru'));if(empty($response['ok']))av_json_response(array('ok'=>false,'error'=>$response['error']??'Банк отклонил возврат','bank_error_code'=>$response['bank_error_code']??''),502);
$orders[$index]['refund_requested_at']=date('c');$orders[$index]['refund_requested_amount']=$amount;$orders[$index]['payment_status']='refund_pending';av_order_event($orders[$index],'payment_refund_requested','Запрошен возврат через Альфа-Банк');if(!av_write_orders($orders))av_json_response(array('ok'=>false,'error'=>'Ошибка записи'),500);av_alfa_payment_log($orders[$index]);av_audit('alfa_refund',$orderId,array('amount'=>$amount));av_json_response(array('ok'=>true,'status'=>'refund_pending','amount'=>$amount));
